444	func TestDeactivationLocksWritesAndReadsButKeepsHistory(t *testing.T) {
445		s, _ := newTestStore(t)
446		pid, eid := setupPatientEncounter(t, s)
447		r, _ := s.CreateDraft(doc, pid, eid, Diagnosis, "草稿")
448		active, _ := s.CreateDraft(doc, pid, eid, Order, "医嘱")
449		if _, err := s.ActivateRecord(doc, active.ID); err != nil {
450			t.Fatal(err)
451		}
452		st := time.Now().Add(-time.Hour)
453		auth, err := s.Grant(doc, pid, rcv.ID, []Scope{{EncounterID: eid, Category: Order}}, st, st.Add(2*time.Hour))
454		if err != nil {
455			t.Fatal(err)
456		}
457	
458		eventsBefore := len(mustAudit(t, s, pid))
459		if err := s.DeactivatePatient(doc, pid); err != nil {
460			t.Fatalf("deactivate: %v", err)
461		}
462		// 重复停用幂等：无额外事件。
463		if err := s.DeactivatePatient(doc, pid); err != nil {
464			t.Fatalf("second deactivate: %v", err)
465		}
466		if got := len(mustAudit(t, s, pid)); got != eventsBefore+1 {
467			t.Fatalf("audit count %d, want %d", got, eventsBefore+1)
468		}
469	
470		if _, err := s.AddEncounter(doc, pid, time.Time{}); !errors.Is(err, ErrDeactivated) {
471			t.Fatalf("add encounter err = %v", err)
472		}
473		if _, err := s.CreateDraft(doc, pid, eid, Diagnosis, "x"); !errors.Is(err, ErrDeactivated) {
474			t.Fatalf("create draft err = %v", err)
475		}
476		if _, err := s.UpdateDraft(doc, r.ID, "x"); !errors.Is(err, ErrDeactivated) {
477			t.Fatalf("update draft err = %v", err)
478		}
479		if err := s.DeleteDraft(doc, r.ID); !errors.Is(err, ErrDeactivated) {
480			t.Fatalf("delete draft err = %v", err)
481		}
482		if _, err := s.ActivateRecord(doc, r.ID); !errors.Is(err, ErrDeactivated) {
483			t.Fatalf("activate err = %v", err)
484		}
485		if _, err := s.CorrectRecord(doc, active.ID, 1, "x", "原因"); !errors.Is(err, ErrDeactivated) {
486			t.Fatalf("correct err = %v", err)
487		}
488		if _, err := s.Grant(doc, pid, "rcv-z", []Scope{{EncounterID: eid, Category: Order}}, st, st.Add(2*time.Hour)); !errors.Is(err, ErrDeactivated) {
489			t.Fatalf("grant err = %v", err)
490		}
491		// 撤回不在停用后的禁止清单内：收缩权限始终允许，且保持幂等。
492		if err := s.Revoke(doc, pid, auth.ID); err != nil {
493			t.Fatalf("revoke after deactivation: %v", err)
494		}
495		nAfterRevoke := len(mustAudit(t, s, pid))
496		if err := s.Revoke(doc, pid, auth.ID); err != nil {
497			t.Fatalf("repeat revoke: %v", err)
498		}
499		if n := len(mustAudit(t, s, pid)); n != nAfterRevoke {
500			t.Fatalf("repeat revoke after deactivation added events: %d -> %d", nAfterRevoke, n)
501		}
502		// 接收方不能继续读取。
503		if _, err := s.Read(rcv, pid, eid, Order); !errors.Is(err, ErrAccessDenied) {
504			t.Fatalf("receiver read err = %v", err)
505		}
506	
507		// 内部使用者仍能查看历史与审计。
508		chart, err := s.Chart(doc, pid)
509		if err != nil {
510			t.Fatal(err)
511		}
512		if !chart.Patient.Deactivated {
513			t.Fatal("chart should show deactivated")
514		}
515		if len(chart.Records) != 2 {
516			t.Fatalf("records = %d, want 2", len(chart.Records))
517		}
518		if auditActions(chart.AuditEvents)[ActionDeactivated] != 1 {
519			t.Fatalf("deactivation audit missing: %+v", chart.AuditEvents)
520		}
